const networkLog = (event, request) => fs.appendFileSync(path.join(OUT,'network.jsonl'),JSON.stringify({at:new Date().toISOString(),event,url:request.url()})+'\n');
ctx.on('request', r => networkLog('request',r));
ctx.on('requestfailed', r => networkLog('requestfailed',r));
await ctx.route(/^https?:\/\//, r => {networkLog('blocked-http',r.request());return r.abort();});
await ctx.setOffline(true);
fs.writeFileSync(path.join(OUT,'network-policy.json'),JSON.stringify({offline:true,httpHttpsRouteAbort:true,serviceWorkers:'block',allowedApp:FILE_URL,noHostNetworkChanges:true},null,2));
